  function createDec(){
  var t=$('f-t');
  if(!t||!t.value.trim())return;
  var cat=$('f-c');
  data.decisions.unshift({
  id:uid(),title:t.value.trim(),description:'',
  category:cat?cat.value:'Other',leaning:'',
  createdAt:Date.now(),resolved:false,resolvedAt:null,
  flow:{options:'',caseFor:'',caseAgainst:'',friendTest:'',confirmation:'',sunkCost:'',anchoring:'',wwhbt:'',premortem:'',earlyWarning:'',provisional:'',challengeAI:'',challengeResponse:'',finalCall:'',debriefKnow:'',debriefSurprise:'',debriefNextTime:''},
  notes:[],_coachMsgs:[]
  });
  saveData();currentModal=null;go('detail',data.decisions[0].id);
  }

  function migrateDecision(d){
  if(d.flow&&!d.flow.completed)d.flow.completed={}; // explicit per-section completion flags
  if(d.flow)return; // already new format
  d.flow={completed:{},options:'',caseFor:'',caseAgainst:'',friendTest:'',confirmation:'',sunkCost:'',anchoring:'',wwhbt:'',premortem:'',earlyWarning:'',provisional:'',challengeAI:'',challengeResponse:'',finalCall:'',debriefKnow:'',debriefSurprise:'',debriefNextTime:''};
  // Migrate scorecard data
  var sc=d.scorecard||{};
  if(sc.decision_q1)d.flow.caseFor=sc.decision_q1+(sc.decision_q2?'\n\nUpsides: '+sc.decision_q2:'');
  if(sc.decision_q3)d.flow.caseAgainst=sc.decision_q3;
  if(sc.assume_q1||sc.assume_q2)d.flow.wwhbt=[sc.assume_q1,sc.assume_q2,sc.assume_q3].filter(Boolean).join('\n');
  if(sc.ignore_q1||sc.ignore_q2)d.flow.confirmation=[sc.ignore_q1,sc.ignore_q2,sc.ignore_q3].filter(Boolean).join('\n');
  // Migrate pre-mortem
  var rt=d.redTeam;
  if(rt&&typeof rt==='object'){
  if(rt.failureStory)d.flow.premortem=rt.failureStory;
  if(rt.hingePoint)d.flow.earlyWarning=rt.hingePoint+(rt.defense?'\n\nDefense: '+rt.defense:'');
  }
  // Migrate check-in/debrief
  var ci=d.checkIn||{};
  if(ci.q0)d.flow.finalCall=ci.q0;
  var db=d.debrief||{};
  if(db.whatHappened)d.flow.debriefKnow=db.whatHappened;
  if(db.mostWrong)d.flow.debriefSurprise=db.mostWrong;
  if(db.nextTime)d.flow.debriefNextTime=db.nextTime;
  if(!d.notes)d.notes=[];
  if(!d._coachMsgs)d._coachMsgs=[];
  }

  function calcPct(d){
  var f=d.flow||{};
  var fields=['options','caseFor','caseAgainst','friendTest','confirmation','sunkCost','anchoring','wwhbt','premortem','earlyWarning','provisional','challengeResponse','finalCall'];
  var n=0;
  for(var i=0;i<fields.length;i++){if(f[fields[i]])n++}
  if(d.leaning)n++;
  return Math.round(n/14*100);
  }

  function sectionDone(d,secId){
  var f=d.flow||{};
  var sec=null;for(var i=0;i<FLOW_SECTIONS.length;i++){if(FLOW_SECTIONS[i].id===secId)sec=FLOW_SECTIONS[i]}
  if(!sec)return false;
  if(secId==='problem')return !!(d.leaning&&f.options);
  if(secId==='challenge')return !!(f.challengeAI&&f.challengeResponse);
  var filled=0;
  for(var i=0;i<sec.fields.length;i++){if(f[sec.fields[i]])filled++}
  return filled===sec.fields.length;
  }

  function applyVibe(){var _dk=(typeof getTheme==='function'&&getTheme()==='dark');V=(_dk&&VIBES[VIBE+'Dark'])?VIBES[VIBE+'Dark']:VIBES[VIBE];
  INK=V.ink;BOARD=V.board;REDI=V.red;SLATE=V.slate;GREEN=V.green;BROWN=V.brown;GOLDT=V.goldT;
  P1=V.p1;P2=V.p2;P3=V.p3;FMAN=V.man;FMAN_D=V.manD;
  BD_PARTS.forEach(function(p){p.color=V[p.ck]});
  CARDS.forEach(function(c){c.stock=V.stocks[c.stockK];c.head=V[c.headK]});}

  function seedSampleData(){
  if(!confirm('Load sample data?\n\nThis replaces the current decisions with the demo set.'))return false;
  if(typeof applyDemoSeed!=='function'){location.reload();return;} // safety fallback
  /* PORTED-IN (tools/port-leader-module.js): the roster lives in the
     workspace here, and applyTeamRoster() rebuilds USERS from it — so a
     wholesale swap signs the reader out. Only program content is replaced. */
  var _acct=data||{};
  data={decisions:[],rev:_acct.rev||0,roster:_acct.roster||null,members:_acct.members||[],enterprise:_acct.enterprise||{},notes:_acct.notes||[],assigns:_acct.assigns||{},orgSetup:_acct.orgSetup||false,startDate:_acct.startDate||null}; /* F-3 fix (ruled July 29): the rev is a write-ordering token, not user content — it must survive the reseed swap or other tabs' refresh guards read the rollback as "no update" and clobber (F-2) */
  applyDemoSeed();
  if(data&&data.decisions){for(var i=0;i<data.decisions.length;i++){migrateDecision(data.decisions[i])}}
  if(!data.assessmentHistory)data.assessmentHistory=[];
  saveData();
  currentPage='home';currentModal=null;currentTab='problem';navHistory=[];
  render();
  window.scrollTo(0,0);
  }

  function buildPresets(d){
  var presets=[];
  var f=d.flow||{};
  var pct=calcPct(d);
  if(!f.caseFor)presets.push({l:'Help me build my case',q:'I haven\'t written my case for and against yet. Help me think through the strongest arguments on both sides. Ask me questions to draw it out.'});
  else presets.push({l:'Challenge my case',q:'Look at my case for and against. Where is my argument weakest? What am I not seeing?'});
  if(!f.premortem)presets.push({l:'Help with the pre-mortem',q:'I haven\'t done the pre-mortem yet. Help me imagine how this decision could fail. Ask me sharp questions to make the failure story vivid and specific.'});
  if(pct>50)presets.push({l:'What am I still missing?',q:'I\'ve done substantial analysis. What gaps remain? What question haven\'t I asked myself?'});
  presets.push({l:'Am I ready to decide?',q:'Based on everything so far, am I ready to make this decision? Or is there more work to do? Be honest.'});
  return presets;
  }

  function goSection(sid){
  navHistory.push(navSnapshot());
  if(navHistory.length>50)navHistory=navHistory.slice(-50);
  currentTab=sid;render();window.scrollTo(0,0);
  }

  function generateProfile(){
  if(decidedCount()<1||profileGenerating)return;
  profileGenerating=true;profileError=false;
  bdRefreshDash();
  fetch(CLAUDE_API_URL,{
  method:'POST',
  headers:{'Content-Type':'application/json'},
  body:JSON.stringify({model:'claude-sonnet-4-20250514',max_tokens:3000,messages:[{role:'user',content:buildProfilePrompt()}]})
  }).then(function(r){return r.json()}).then(function(j){
  var text='';
  if(j.content){for(var ci=0;ci<j.content.length;ci++)if(j.content[ci].text)text+=j.content[ci].text}
  if(!text)text='Could not generate profile. Try again.';
  if(!data.profile)data.profile={};
  data.profile.text=text;
  data.profile.generatedAt=Date.now();
  data.profile.decisionCount=decidedCount();
  profileGenerating=false;
  saveData();
  bdRefreshDash();
  }).catch(function(err){
  console.error('Profile error:',err);
  profileGenerating=false;profileError=true;
  bdRefreshDash();
  });
  }

