  function buildCoachContext(d){
  var ctx='DECISION: "'+d.title+'"\n';
  ctx+='CONTEXT: "'+d.description+'"\n';
  ctx+='LEANING: "'+(d.leaning||'Not stated')+'"\n';
  var f=d.flow||{};
  if(f.options)ctx+='OPTIONS CHECK: "'+f.options+'"\n';
  if(f.caseFor)ctx+='CASE FOR: "'+f.caseFor+'"\n';
  if(f.caseAgainst)ctx+='CASE AGAINST: "'+f.caseAgainst+'"\n';
  if(f.friendTest)ctx+='FRIEND TEST: "'+f.friendTest+'"\n';
  if(f.confirmation)ctx+='CONFIRMATION BIAS: "'+f.confirmation+'"\n';
  if(f.sunkCost)ctx+='SUNK COST: "'+f.sunkCost+'"\n';
  if(f.anchoring)ctx+='ANCHORING: "'+f.anchoring+'"\n';
  if(f.wwhbt)ctx+='WHAT WOULD HAVE TO BE TRUE: "'+f.wwhbt+'"\n';
  if(f.premortem)ctx+='PRE-MORTEM: "'+f.premortem+'"\n';
  if(f.earlyWarning)ctx+='EARLY WARNING: "'+f.earlyWarning+'"\n';
  if(f.provisional)ctx+='PROVISIONAL DECISION: "'+f.provisional+'"\n';
  if(f.challengeAI)ctx+='AI CHALLENGE: "'+f.challengeAI.substring(0,200)+'"\n';
  if(f.challengeResponse)ctx+='CHALLENGE RESPONSE: "'+f.challengeResponse+'"\n';
  if(f.finalCall)ctx+='FINAL CALL: "'+f.finalCall+'"\n';
  return ctx;
  }

