  function decidedCount(){var n=0;data.decisions.forEach(function(d){if((d.flow||{}).finalCall)n++});return n}

  function bdRefreshDash(){var _bs=document.getElementById('boardStage');if(currentPage==='dashboard'&&_bs&&_bs.classList.contains('stage-full')){bdRenderDash();}else{render();}}

  function buildProfilePrompt(){
  var qKeys=['description','leaning','options','caseFor','caseAgainst','friendTest','confirmation','sunkCost','anchoring','wwhbt','premortem','earlyWarning','provisional'];
  var qList=qKeys.map(function(k,i){return (i+1)+'. '+qText(k)}).join('\n');
  var pool=data.decisions.filter(function(d){return d.flow&&d.flow.finalCall});
  var ctx='DECIDED DECISIONS: '+pool.length+'\n\n';
  for(var i=0;i<pool.length;i++){
  var d=pool[i],f=d.flow||{};
  ctx+='--- DECISION '+(i+1)+': "'+d.title+'" ('+d.category+') ---\n';
  ctx+='Status: '+(d.resolved?'Resolved':'Active')+'\n';
  if(d.description)ctx+='Problem/context: "'+d.description+'"\n';
  if(d.leaning)ctx+='Initial leaning: "'+d.leaning+'"\n';
  if(f.options)ctx+='Options check: "'+f.options+'"\n';
  if(f.caseFor)ctx+='Case for: "'+f.caseFor+'"\n';
  if(f.caseAgainst)ctx+='Case against: "'+f.caseAgainst+'"\n';
  if(f.friendTest)ctx+='Friend test: "'+f.friendTest+'"\n';
  if(f.confirmation)ctx+='Confirmation bias check: "'+f.confirmation+'"\n';
  if(f.sunkCost)ctx+='Sunk cost check: "'+f.sunkCost+'"\n';
  if(f.anchoring)ctx+='Anchoring check: "'+f.anchoring+'"\n';
  if(f.wwhbt)ctx+='What would have to be true to be wrong: "'+f.wwhbt+'"\n';
  if(f.premortem)ctx+='Pre-mortem: "'+f.premortem+'"\n';
  if(f.earlyWarning)ctx+='Early warning: "'+f.earlyWarning+'"\n';
  if(f.provisional)ctx+='Provisional decision: "'+f.provisional+'"\n';
  if(f.challengeAI)ctx+='AI challenge given: "'+f.challengeAI+'"\n';
  if(f.challengeResponse)ctx+='Their response to challenge: "'+f.challengeResponse+'"\n';
  if(f.finalCall)ctx+='Final call: "'+f.finalCall+'"\n';
  if(f.provisional&&f.finalCall&&f.provisional.trim()!==f.finalCall.trim())ctx+='NOTE: They changed their mind during the process.\n';
  if(f.debriefKnow)ctx+='Debrief - what they know now: "'+f.debriefKnow+'"\n';
  if(f.debriefSurprise)ctx+='Debrief - what surprised them: "'+f.debriefSurprise+'"\n';
  if(f.debriefNextTime)ctx+='Debrief - lesson for next time: "'+f.debriefNextTime+'"\n';
  var skipped=[];
  if(!f.options)skipped.push('Options check');
  if(!f.caseAgainst)skipped.push('Case against');
  if(!f.friendTest)skipped.push('Friend test');
  if(!f.confirmation)skipped.push('Confirmation bias');
  if(!f.sunkCost)skipped.push('Sunk cost');
  if(!f.anchoring)skipped.push('Anchoring');
  if(!f.wwhbt)skipped.push('WWHBT');
  if(!f.premortem)skipped.push('Pre-mortem');
  if(!f.earlyWarning)skipped.push('Early warning');
  if(skipped.length)ctx+='Sections skipped: '+skipped.join(', ')+'\n';
  ctx+='\n';
  }
  var sysPrompt='You are the Decision Profile Analyst inside the Judgment \u2014 Critical Thinking app, a decision-training module in NextChapter\'s Leadership Edge program. The app trains one skill: making better decisions by examining your own thinking. The person works through real decisions from their life and work in a structured sequence. They state the problem and their initial leaning, check whether they have real alternatives, argue the case for and against, run a friend test, check themselves for confirmation bias, sunk cost, and anchoring, describe what would have to be true for them to be wrong, write a pre-mortem failure story, set an early warning sign, and make a provisional decision. An AI then challenges their reasoning, they respond, make their final call, and close the file with a debrief on what they learned. Your job is to read everything they wrote across all of their decisions and hold up an honest mirror: how this person actually decides, where their judgment is strong, where it fails them, and what to work on next. The profile you write appears on their Dashboard and is a core part of their training.\n\nThese are the questions they answered in each decision:\n'+qList+'\n\nWrite a decision profile for them. This should be:\n\n1. GENUINE INSIGHT, not flattery. Read the actual content of what they wrote and identify real patterns.\n\n2. Structured as:\n- WHO THEY ARE AS A DECIDER (2-3 sentences capturing their core tendencies)\n- STRENGTHS (what they genuinely do well, with evidence from their decisions)\n- BLIND SPOTS (what they consistently miss, avoid, or get wrong \u2014 be specific)\n- PATTERNS (recurring themes across decisions: what surprises them, what lessons repeat, whether they change their mind, what kinds of failure they imagine)\n- FOR NEXT TIME (2-3 specific things to focus on in their next decision, based on actual evidence)\n\n3. Written in second person ("you tend to..."), direct, warm, no hedging. If something is clearly a weakness, say so. If a debrief lesson keeps repeating, point out they haven\'t learned it yet.\n\n4. Keep it to roughly 400-600 words total. Dense with insight, no filler.\n\nIMPORTANT: Base everything on what they ACTUALLY WROTE. Don\'t invent patterns that aren\'t there. If the data is thin, say so \u2014 "you\'ve only completed N decisions, so patterns are provisional" \u2014 but still give what insight you can.';
  return sysPrompt+'\n\nHere is the data:\n'+ctx;
  }

  function dlDownload(name,text){
  var blob=new Blob([text],{type:'text/markdown'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();
  setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url)},0);
  }

  function buildAIState1Md(){
  var md='# Judgment \u2014 AI State Export 1: Challenge Prompts\n\n';
  md+='Exported '+fmt(Date.now())+'.\n\n';
  md+='Each section below is the exact prompt the Judgment \u2014 Critical Thinking app sends to the AI to compose the Challenge for that decision. Paste a section into Claude to see the challenge it would generate.\n\n';
  var n=0;
  data.decisions.forEach(function(d){var f=d.flow||{};
  if(!f.provisional)return;n++;
  md+='---\n\n## '+n+'. '+d.title+'\n\n';
  md+='```\n'+buildChallengePrompt(d).sys+'\n```\n\n';
  });
  if(!n)md+='_No decision has reached the Challenge stage yet. The Challenge is composed once a provisional decision is filed._\n';
  return md;
  }

  function buildAIState2Md(){
  var md='# Judgment \u2014 AI State Export 2: Written Profile Prompt\n\n';
  md+='Exported '+fmt(Date.now())+' \u00B7 '+data.decisions.length+' decision(s), '+decidedCount()+' decided.\n\n';
  md+='Below is the exact prompt the Judgment \u2014 Critical Thinking app sends to the AI when the written profile is generated or regenerated. Paste it into Claude to see the profile it would produce from the current decisions.\n\n';
  if(decidedCount()<1)md+='_Note: the in-app Generate button unlocks once one decision reaches its final call. This export shows the prompt as it stands anyway._\n\n';
  md+='```\n'+buildProfilePrompt()+'\n```\n';
  return md;
  }

  function on(id,fn){var e=document.getElementById(id);if(e)e.addEventListener('click',fn)}

  function boardTier(){if(typeof window!=='undefined'&&window.__forceTier)return window.__forceTier;
  var iw=(typeof window!=='undefined'&&window.innerWidth)||1500;
  var z=(window.UI&&UI.zoom)||1;   /* PORTED-IN: the shell owns the zoom. */
  var lay=Math.min((iw-40)/z,iw>=1560?1472:1280);
  var vis=lay*z;
  var det=(typeof currentPage!=='undefined'&&currentPage==='detail');
  if(det){var diw=iw/z*1;return iw>=1320*z?'wide':(iw>=716*z?'mid':'narrow')}
  return vis>=1170?'wide':(vis>=700?'mid':'narrow')}

  function buildFilesSVG(list,expanded){
  var st={active:[],decided:[],resolved:[]};
  list.forEach(function(d,i){st[decStatus(d)].push(i)});
  var order=st.active.concat(st.decided,st.resolved);
  var showN=expanded?order.length:Math.min(6,order.length);
  var slots=Math.max(6,Math.ceil(showN/3)*3);
  if(expanded)slots=Math.ceil(order.length/3)*3;
  var rows=slots/3;
  var gy0=352,rowH=196;
  var Hf=gy0+rows*rowH+(order.length>6?70:40)+40;
  var s='<svg viewBox="0 0 '+W+' '+Hf+'" xmlns="http://www.w3.org/2000/svg">'+boardDefs();
  s+=boardSurface(W,Hf);
  s+='<line x1="70" y1="308" x2="'+(W-70)+'" y2="308" stroke="'+INK+'" stroke-width="0.8" opacity="'+(V.tex?0.14:0.13)+'"/>';
  s+=filesHeaderCard()+newFolder();
  var xs=[96,560,1024];
  for(var k=0;k<slots;k++){
  var col=k%3,row=Math.floor(k/3);
  var x=xs[col],y=gy0+row*rowH;
  if(k<showN)s+=folderSVG(list[order[k]],order[k],x,y);
  else s+=ghostFolder(x,y);
  }
  if(order.length>6)s+=filesPullTab(order.length,expanded,gy0+rows*rowH+8);
  s+='</svg>';return s}

