  function tryOpen(sec,key){
  if(!sec)return;
  /* Module semantics: every section is freely navigable; completion is the
     explicit stamp (gated Mark Complete), not a lock. */
  if(sec==='challenge'&&!bdD.flow.challengeAI&&!bdChallengePending){bdChallengeError=false;bdGenerateChallenge()}
  bdIntroShow=false;focusSec=sec;focusQ=0;
  if(key){var qs=SECTIONS[sec].qs;for(var i=0;i<qs.length;i++)if(qs[i].key===key)focusQ=i}
  openedKey=key||SECTIONS[sec].qs[0].key;
  var _pt=bdPartOf(sec);
  focusPanel=vidSeen[_pt.id]?(((bdD.flow.completed||{})[sec])?null:'car'):'vid'; /* completed-card exception preserved (Paul's veto, July 28): a finished step opens with both panels closed */
  if(!vidSeen[_pt.id]){vidSeen[_pt.id]=true;try{Store.setPref('vidseen',JSON.stringify(vidSeen))}catch(e){}}
  carIdx=0;specOpen=false;
  renderFocus();
  var from=cardRect(openedKey);
  liftSource(openedKey,true);
  flipOpen(from);
  }

