  function bdAssessState(){
  var a=assessRetakeBuf||data.assessment||{}; /* F-4/C: a live retake presents the buffer; its missing completedAt keeps the question flow on screen while the persisted diagnostics stay intact underneath */
  var completed=!!(a.completedAt&&a.scores);
  var hist=(data.assessmentHistory||[]).slice().sort(function(x,y){return x.completedAt-y.completedAt});
  var histView=hist.map(function(e){return {scores:e.scores,dateStr:fmt(e.completedAt),_at:e.completedAt}});
  var histIdx=null;
  if(assessHistIdx!==null&&data.assessmentHistory[assessHistIdx]){
  var at=data.assessmentHistory[assessHistIdx].completedAt;
  histView.forEach(function(e,i){if(e._at===at)histIdx=i});
  }
  var step=(completed&&assessStep===0)?'done':assessStep;
  return {step:step,answers:(a.answers||{}),scores:a.scores||null,dateStr:a.completedAt?fmt(a.completedAt):'',history:histView,histIdx:histIdx};
  }

