  function bdDashModel(){
  var res=[],dec=[],days=[];
  data.decisions.forEach(function(d){var f=d.flow||{};
  if(d.resolved)res.push(d);else if(f.finalCall)dec.push(d);
  if(f.finalCall){var a=daysSince(d.createdAt);if(a)days.push(a)}});
  var assess=data.assessment||{};
  var hasAssess=!!(assess.completedAt&&assess.scores);
  var profile=null;
  if(data.profile&&data.profile.text){
  var pp=parseProfileP(data.profile.text);
  profile={quote:pp.identity,cards:[
  {title:'STRENGTHS',icon:'\u2726',ck:'green',text:pp.strengths||''},
  {title:'BLIND SPOTS',icon:'\u25C9',ck:'red',text:pp.blindspots||''},
  {title:'PATTERNS',icon:'\u25C8',ck:'p1',text:pp.patterns||''},
  {title:'FOR NEXT TIME',icon:'\u2192',ck:'goldT',text:pp.nexttime||''}]};
  }
  var playbook=[];data.decisions.forEach(function(d){var f=d.flow||{};
  if(f.debriefNextTime)playbook.push({num:(playbook.length+1<10?'0':'')+(playbook.length+1),title:truncTitle(d.title,32),dateStr:fmt(d.createdAt),text:f.debriefNextTime,idx:d.id})});
  var byRecency=data.decisions.slice().sort(function(a,b){return daysSince(a.createdAt)-daysSince(b.createdAt)}).slice(0,4);
  var acts=byRecency.map(function(d){var f=d.flow||{};var phrase='Filed Decision Closed';
  if(!d.resolved){if(f.finalCall)phrase='Awaiting debrief';else{var last=null;CARDS.forEach(function(c){if(f[c.key])last=c.label});phrase=last?bdTitleCase(last)+' filed':'File opened'}}
  return {title:truncTitle(d.title,26),phrase:phrase,when:daysSince(d.createdAt)+'d ago',color:catColor(d)||V.goldT,idx:d.id}});
  var loops=res.slice(0,3).map(function(d){return {t:truncTitle(d.title,14).toUpperCase(),full:d.title,mon:fmt(d.createdAt).slice(0,3).toUpperCase(),cat:d.category,idx:d.id}});
  var nudges=buildNudges();
  var nudgeMap={};
  for(var ni=0;ni<nudges.length;ni++){
  for(var ndi=0;ndi<data.decisions.length;ndi++){
  if(nudges[ni].text.indexOf(esc(data.decisions[ndi].title))>=0)nudgeMap[data.decisions[ndi].id]=nudges[ni];
  }
  }
  var order=data.decisions.slice().sort(function(a,b){var aN=nudgeMap[a.id]?1:0,bN=nudgeMap[b.id]?1:0;return bN-aN||b.createdAt-a.createdAt});
  var rows=order.map(function(d){var f=d.flow||{};
  return {idx:d.id,title:d.title,cat:d.category,catCol:catColor(d)||V.goldT,resolved:!!d.resolved,

  dateStr:fmt(d.createdAt)+' \u00B7 '+daysSince(d.createdAt)+'d',done:Object.keys(f.completed||{}).length,total:8,nudge:nudgeMap[d.id]||null}});
  return {opened:data.decisions.length,closed:res.length,awaiting:dec.length,
  avgDays:days.length?Math.round(days.reduce(function(a,b){return a+b},0)/days.length):0,
  cta:false,self:hasAssess?assess.scores:null,revealed:data.decisions.length?buildRevealedScores():null,
  profile:profile,pstate:{decided:decidedCount(),total:data.decisions.length,generating:profileGenerating,error:profileError,decisionCount:(data.profile||{}).decisionCount||0,stale:!!(data.profile&&data.profile.text&&decidedCount()>data.profile.decisionCount),caption:(data.profile&&data.profile.text?'BASED ON '+data.profile.decisionCount+' DECISIONS \u00B7 GENERATED '+fmt(data.profile.generatedAt):'')},playbook:playbook,acts:acts,loops:loops,rows:rows};
  }

