  function sectionPct(d,secId){
  var f=d.flow||{};
  var sec=null;for(var i=0;i<FLOW_SECTIONS.length;i++){if(FLOW_SECTIONS[i].id===secId)sec=FLOW_SECTIONS[i]}
  if(!sec)return 0;
  if(secId==='problem')return(d.leaning?50:0)+(f.options?50:0);
  if(secId==='challenge'){var n=0;if(f.challengeAI)n+=50;if(f.challengeResponse)n+=50;return n}
  var filled=0;
  for(var i=0;i<sec.fields.length;i++){if(f[sec.fields[i]])filled++}
  return sec.fields.length?Math.round(filled/sec.fields.length*100):0;
  }

  function qText(key){for(var sk in SECTIONS){var qs=SECTIONS[sk].qs||[];for(var i=0;i<qs.length;i++)if(qs[i].key===key)return qs[i].label}return ''}

  function buildChallengePrompt(d){
  var f=d.flow||{};
  function ex(label,key,val){var q=qText(key);var out=label+'\n';if(q)out+='QUESTION ASKED: "'+q+'"\n';out+='THEIR ANSWER: "'+val+'"\n\n';return out}
  var ctx='DECISION: "'+d.title+'"\n\n';
  ctx+=ex('PROBLEM/CONTEXT','description',d.description);
  ctx+=ex('LEANING','leaning',(d.leaning||'Not stated'));
  ctx+=ex('OPTIONS CHECK','options',(f.options||'Not answered'));
  ctx+=ex('CASE FOR','caseFor',(f.caseFor||'Not answered'));
  ctx+=ex('CASE AGAINST','caseAgainst',(f.caseAgainst||'Not answered'));
  ctx+=ex('FRIEND TEST','friendTest',(f.friendTest||'Not answered'));
  ctx+=ex('CONFIRMATION BIAS CHECK','confirmation',(f.confirmation||'Not answered'));
  ctx+=ex('SUNK COST CHECK','sunkCost',(f.sunkCost||'Not answered'));
  ctx+=ex('ANCHORING CHECK','anchoring',(f.anchoring||'Not answered'));
  ctx+=ex('WHAT WOULD HAVE TO BE TRUE TO BE WRONG','wwhbt',(f.wwhbt||'Not answered'));
  ctx+=ex('PRE-MORTEM FAILURE STORY','premortem',(f.premortem||'Not answered'));
  ctx+=ex('EARLY WARNING SIGN','earlyWarning',(f.earlyWarning||'Not answered'));
  ctx+=ex('PROVISIONAL DECISION','provisional',(f.provisional||'Not answered'));

  var caseForLen=(f.caseFor||'').split(/\s+/).length;
  var caseAgainstLen=(f.caseAgainst||'').split(/\s+/).length;
  ctx+='NOTE: Case-for is approximately '+caseForLen+' words. Case-against is approximately '+caseAgainstLen+' words.\n';

  var sysPrompt='You are a Decision Challenger inside the Judgment \u2014 Critical Thinking app, a decision-training tool. You have the user\'s complete decision analysis below.\n\n'+ctx+'\n\nYour task: deliver ONE sharp, specific challenge that this person has not considered. Your challenge should:\n- Reference their SPECIFIC words and surface contradictions between sections\n- Name any cognitive biases you see operating, citing evidence from their actual answers\n- Point out asymmetries (e.g., case-for was much longer/more detailed than case-against)\n- Note anything thin, missing, or suspiciously confident\n- Be direct, warm, and impossible to dismiss with a hand-wave\n- End with ONE pointed question they must answer\n- Keep to 2-3 paragraphs maximum\n- NEVER make the decision for them. Your job is to make their thinking sharper, not to think for them.\n- Write in a direct, slightly provocative but warm tone. Like a trusted advisor who respects them enough to be honest.';
  return {ctx:ctx,sys:sysPrompt};
  }

  function decStatus(d){return d.resolved?'resolved':(d.flow.finalCall?'decided':'active')}

  function boardDefs(){return '<defs>'
  +'<filter id="bgrain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed="5" result="n"/><feColorMatrix in="n" type="matrix" values="0 0 0 0 0.36 0 0 0 0 0.31 0 0 0 0 0.24 0 0 0 0.05 0"/><feComposite operator="over" in2="SourceGraphic"/></filter>'
  +'<filter id="weave" x="0" y="0" width="100%" height="100%"><feTurbulence type="turbulence" baseFrequency="0.012 0.11" numOctaves="2" seed="8" result="n"/><feColorMatrix in="n" type="matrix" values="0 0 0 0 0.30 0 0 0 0 0.26 0 0 0 0 0.20 0 0 0 0.045 0"/><feComposite operator="over" in2="SourceGraphic"/></filter>'
  +'<filter id="cardsh" x="-30%" y="-30%" width="160%" height="160%">'+(V.tex?'':'<feDropShadow dx="0" dy="1" stdDeviation="1.1" flood-color="#1E2530" flood-opacity="0.18"/>')+'<feDropShadow dx="'+V.sh.dx+'" dy="'+V.sh.dy+'" stdDeviation="'+V.sh.bl+'" flood-color="'+V.sh.col+'" flood-opacity="'+V.sh.op+'"/></filter>'
  +'<filter id="pinsh" x="-80%" y="-80%" width="260%" height="260%"><feDropShadow dx="0.8" dy="1.8" stdDeviation="1.4" flood-color="'+V.sh.col+'" flood-opacity="'+V.pinSh+'"/></filter>'
  +'<radialGradient id="vign" cx="50%" cy="46%" r="78%"><stop offset="62%" stop-color="#2A241C" stop-opacity="0"/><stop offset="100%" stop-color="#2A241C" stop-opacity="0.15"/></radialGradient>'
  +'<pattern id="dots" width="26" height="26" patternUnits="userSpaceOnUse"><circle cx="13" cy="13" r="1.05" fill="#1E2530" opacity="0.08"/></pattern>'
  +'<linearGradient id="toplight" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFFFFF" stop-opacity="0.45"/><stop offset="1" stop-color="#FFFFFF" stop-opacity="0"/></linearGradient>' 
  +'</defs>'}

  function boardSurface(Wd,Ht){var h='<rect width="'+Wd+'" height="'+Ht+'" rx="'+V.rx+'" fill="'+BOARD+'"/>';
  if(V.tex){h+='<rect width="'+Wd+'" height="'+Ht+'" fill="'+BOARD+'" filter="url(#weave)" opacity="0.9"/>';
  h+='<rect width="'+Wd+'" height="'+Ht+'" fill="'+BOARD+'" filter="url(#bgrain)" opacity="0.7"/>';
  h+='<rect width="'+Wd+'" height="'+Ht+'" fill="url(#vign)"/>';
  h+='<rect x="16" y="16" width="'+(Wd-32)+'" height="'+(Ht-32)+'" fill="none" stroke="'+INK+'" stroke-width="3"/>';
  h+='<rect x="28" y="28" width="'+(Wd-56)+'" height="'+(Ht-56)+'" fill="none" stroke="'+INK+'" stroke-width="0.8" opacity="0.55"/>';}
  else{h+='<rect width="'+Wd+'" height="'+Ht+'" rx="'+V.rx+'" fill="url(#dots)"/>';
  h+='<rect width="'+Wd+'" height="260" rx="'+V.rx+'" fill="url(#toplight)"/>';
  h+='<rect x="16" y="16" width="'+(Wd-32)+'" height="'+(Ht-32)+'" rx="10" fill="none" stroke="rgba(30,37,48,0.30)" stroke-width="1.5"/>';
  [[30,30],[Wd-30,30],[30,Ht-30],[Wd-30,Ht-30]].forEach(function(p){h+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="2.6" fill="rgba(30,37,48,0.28)"/><circle cx="'+(p[0]-0.8)+'" cy="'+(p[1]-0.8)+'" r="0.8" fill="#FFFFFF" opacity="0.5"/>'});}
  return h}

