  if(isCur)g+='<g transform="rotate('+(2*V.rotM)+' '+(c.x+c.w-34)+' '+(c.y+c.h-14)+')"><rect x="'+(c.x+c.w-62)+'" y="'+(c.y+c.h-24)+'" width="52" height="18" rx="'+(V.rail?9:0)+'" fill="'+GOLDT+'" opacity="0.92"/><text x="'+(c.x+c.w-36)+'" y="'+(c.y+c.h-11)+'" font-family="DM Mono" font-size="8.5" letter-spacing="1.5" text-anchor="middle" fill="'+V.white+'">OPEN \u2192</text></g>';
  g+='</g>';
