  function procLine(a,b){
  var ax,ay,bx,by,d,dir,pts;
  if(b.y>=a.y+a.h-10){ax=a.x+a.w/2;ay=a.y+a.h;bx=b.x+b.w/2;by=b.y;dir='down';}
  else if(b.x>=a.x+a.w-10){ax=a.x+a.w;ay=a.y+a.h/2;bx=b.x;by=b.y+b.h/2;dir='right';}
  else{ax=a.x+a.w/2;ay=a.y;bx=b.x+b.w/2;by=b.y+b.h;dir='up';}
  var len=Math.abs(ax-bx)+Math.abs(ay-by);
  if(len<=130){if(dir==='right'){ay=by;}else{ax=bx;}d='M '+ax+','+ay+' L '+bx+','+by;pts=[[ax,ay],[bx,by]];}
  else if(dir==='right'){var mx=(ax+bx)/2;d='M '+ax+','+ay+' L '+mx+','+ay+' L '+mx+','+by+' L '+bx+','+by;pts=[[ax,ay],[mx,ay],[mx,by],[bx,by]];}
  else{var my=(ay+by)/2;d='M '+ax+','+ay+' L '+ax+','+my+' L '+bx+','+my+' L '+bx+','+by;pts=[[ax,ay],[ax,my],[bx,my],[bx,by]];}
  var arrow=dir==='down'?('<polygon points="'+(bx-4)+','+(by-7)+' '+(bx+4)+','+(by-7)+' '+bx+','+by+'"'):
  (dir==='right'?('<polygon points="'+(bx-7)+','+(by-4)+' '+(bx-7)+','+(by+4)+' '+bx+','+by+'"'):
  ('<polygon points="'+(bx-4)+','+(by+7)+' '+(bx+4)+','+(by+7)+' '+bx+','+by+'"'));
  var mid='';
  if(len>130){var tot=0,segs=[],i;for(i=0;i<pts.length-1;i++){var sl=Math.abs(pts[i+1][0]-pts[i][0])+Math.abs(pts[i+1][1]-pts[i][1]);segs.push(sl);tot+=sl}
  var half=tot/2,acc=0;
  for(i=0;i<segs.length;i++){if(acc+segs[i]>=half){var f=segs[i]?(half-acc)/segs[i]:0;
  var px=pts[i][0]+(pts[i+1][0]-pts[i][0])*f,py=pts[i][1]+(pts[i+1][1]-pts[i][1])*f;
  var ang=Math.atan2(pts[i+1][1]-pts[i][1],pts[i+1][0]-pts[i][0])*180/Math.PI;
  mid='<polygon class="t-mid" points="-3.5,-3.5 -3.5,3.5 4.5,0" transform="translate('+px.toFixed(1)+','+py.toFixed(1)+') rotate('+ang.toFixed(0)+')"';break}
  acc+=segs[i]}}
  return {d:d,arrow:arrow,mid:mid}}

