  function computeAssessScores(ansOpt){ /* F-4/C: optional answers param for the retake-buffer commit; zero-arg callers read the persisted record as before */
  var a=ansOpt||(data.assessment&&data.assessment.answers?data.assessment.answers:{});
  var sums={},counts={};
  for(var i=0;i<ASSESS_DIMS.length;i++){sums[ASSESS_DIMS[i].id]=0;counts[ASSESS_DIMS[i].id]=0}
  for(var qi=0;qi<ASSESS_QS.length;qi++){
  var ans=a['q'+qi];
  if(ans===undefined)continue;
  var q=ASSESS_QS[qi];
  for(var di=0;di<q.dims.length;di++){
  var dm=q.dims[di];
  var val=ans===0?dm.a:ans===100?dm.b:Math.round((dm.a+dm.b)/2);
  sums[dm.d]+=val;counts[dm.d]++;
  }
  }
  var scores={};
  for(var i=0;i<ASSESS_DIMS.length;i++){
  var id=ASSESS_DIMS[i].id;
  scores[id]=counts[id]>0?Math.round(sums[id]/counts[id]):50;
  }
  return scores;
  }

  function archiveAssessment(a){
  if(!a||!a.completedAt||!a.scores)return;
  if(!data.assessmentHistory)data.assessmentHistory=[];
  for(var i=0;i<data.assessmentHistory.length;i++){if(data.assessmentHistory[i].completedAt===a.completedAt)return}
  data.assessmentHistory.push({answers:JSON.parse(JSON.stringify(a.answers||{})),scores:JSON.parse(JSON.stringify(a.scores||{})),completedAt:a.completedAt});
  }

