  function jumpQ(i){focusQ=i;renderFocus()}

  function bdMarkComplete(){
  if(!bdSectionDone(focusSec))return;
  if(!bdD.flow.completed)bdD.flow.completed={};
  bdD.flow.completed[focusSec]=true;
  SECTIONS[focusSec].qs.forEach(function(q){pendingAnim.push(q.key)});
  var idx=ORDER.indexOf(focusSec),sec=focusSec;
  var wasDebrief=(sec==='debrief');
  var landKey=openedKey||SECTIONS[sec].qs[0].key;
  focusSec=null;
  if(wasDebrief){bdD.resolved=true;bdD.resolvedAt=Date.now();/* F-6 fix (ruled July 29): app-sealed decisions now carry the timestamp the seed schema always had */currentSec=null}else{currentSec=ORDER[idx+1]}
  saveData();
  flipClose(landKey,function(){renderBoard()});
  }

  function reducedMotion(){try{return window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches}catch(e){return false}}

  function assessGuidanceTips(scores){var tips=[];
  if(scores.head_gut>=60)tips.push('Pay extra attention to the Bias Check \u2014 intuitive deciders often arrive at a position before they\u2019ve examined it. The process is designed to slow that down.');
  else if(scores.head_gut<=40)tips.push('Watch for analysis paralysis in the Stress Test. Your instinct will be to find more data. At some point, you have to decide with what you have.');
  if(scores.fast_slow<=40)tips.push('The Pre-Mortem section is built for you \u2014 it forces the slow, imaginative thinking you are inclined to skip. Don\u2019t rush it.');
  else if(scores.fast_slow>=60)tips.push('Set a time limit for the overall process. Your instinct to deliberate is a strength, but it can become avoidance.');
  if(scores.bold_cautious<=40)tips.push('The Case Against is the most important question for you. Bold deciders tend to write thin counter-arguments. Make yours substantial.');
  else if(scores.bold_cautious>=60)tips.push('Challenge yourself to make your Provisional Decision before you feel completely ready. Waiting for certainty is its own kind of risk.');
  if(scores.solo_social<=40)tips.push('The Friend Test is your most important question \u2014 it forces the external perspective you naturally skip.');
  else if(scores.solo_social>=60)tips.push('Write your Case For before consulting anyone. This app is about building YOUR judgment muscle, not collecting opinions.');
  if(scores.opt_prag<=40)tips.push('The Options Check is where you\u2019ll shine \u2014 but set a limit. Three options is enough. Don\u2019t let the search for more become the decision.');
  else if(scores.opt_prag>=60)tips.push('Force yourself to write at least 3\u20134 sentences for each question. Your instinct is to resolve quickly and move on \u2014 depth is where you can earn additional insight.');
  if(!tips.length)tips.push('Your balanced profile means no single section is a weak spot \u2014 but watch for the temptation to coast. The sections that feel easiest are often where you\u2019re least challenged.');
  return tips}

  function assessGhosts(excludeCompletedAt){
  var h=(data.assessmentHistory||[]).slice().sort(function(a,b){return (b.completedAt||0)-(a.completedAt||0)});
  var out=[];for(var i=0;i<h.length&&out.length<3;i++){if(h[i]&&h[i].scores&&h[i].completedAt!==excludeCompletedAt)out.push({scores:h[i].scores,completedAt:h[i].completedAt})}
  return out;}

  function bdDimRuler(x,ty,w,dm,sc,fs){
  fs=fs||1;var mid=x+w/2,unit=(w/2)/5,units=Math.abs(sc-50)/10,sign=sc>=50?1:-1;
  var num=Math.max(18,Math.round(11.5*fs*10)/10);
  var s='<line x1="'+x+'" y1="'+ty+'" x2="'+(x+w)+'" y2="'+ty+'" stroke="'+INK+'" stroke-width="1" opacity="0.3"/>';
  for(var u=-5;u<=5;u++){var tx=mid+u*unit,major=(u===0);
  s+='<line x1="'+tx+'" y1="'+(ty-(major?9:5))+'" x2="'+tx+'" y2="'+(ty+(major?9:5))+'" stroke="'+INK+'" stroke-width="'+(major?2:1)+'" opacity="'+(major?0.6:0.35)+'"/>';}
  s+='<text x="'+x+'" y="'+(ty+num+12)+'" font-family="DM Mono" font-size="'+num+'" fill="'+INK+'" opacity="0.45">5</text>';
  s+='<text x="'+(mid-16)+'" y="'+(ty+num+12)+'" text-anchor="end" font-family="DM Mono" font-size="'+num+'" fill="'+INK+'" opacity="0.5">0</text>'; /* zeros flank the centre tick (July 28 ruling) */
  s+='<text x="'+(mid+16)+'" y="'+(ty+num+12)+'" text-anchor="start" font-family="DM Mono" font-size="'+num+'" fill="'+INK+'" opacity="0.5">0</text>';
  s+='<text x="'+(x+w)+'" y="'+(ty+num+12)+'" text-anchor="end" font-family="DM Mono" font-size="'+num+'" fill="'+INK+'" opacity="0.45">5</text>';
  if(units>0.05){
  var bx=sign>0?mid:mid+sign*units*unit;
  s+='<rect x="'+bx+'" y="'+(ty-6.5)+'" width="'+(units*unit)+'" height="13" fill="'+V[dm.ck]+'"/>';
  var vx=mid+sign*units*unit+sign*14;
  s+='<text x="'+vx+'" y="'+(ty+6)+'" text-anchor="'+(sign>0?'start':'end')+'" font-family="DM Mono" font-size="19" font-weight="bold" fill="'+V[dm.ck]+'">'+(Math.round(units*10)/10)+'</text>';
  }else{
  s+='<circle cx="'+mid+'" cy="'+ty+'" r="5.5" fill="none" stroke="'+V[dm.ck]+'" stroke-width="2.4"/>';
  s+='<text x="'+mid+'" y="'+(ty-15)+'" text-anchor="middle" font-family="DM Mono" font-size="18" letter-spacing="1.5" fill="'+INK+'" opacity="0.45">BALANCED</text>'; /* above the zero, below the pole labels, faded (July 28 ruling); 18 is the Part VII floor */}
  return s;}

