  function flipClose(landKey,done){
  var bg=document.getElementById('focusBg'),card=document.getElementById('focusCard'),inner=document.getElementById('focusInner');
  var to=landKey?cardRect(landKey):null;
  if(!to||reducedMotion()){bg.classList.remove('open');if(done)done();return}
  var from=card.getBoundingClientRect();
  inner.style.transition='opacity .14s ease';inner.style.opacity=0;
  card.style.transformOrigin='top left';
  card.style.transition='transform .4s cubic-bezier(.5,0,.3,1)';
  card.style.transform='translate('+(to.left-from.left)+'px,'+(to.top-from.top)+'px) scale('+(to.width/from.width)+','+(to.height/from.height)+')';
  bg.classList.remove('open');
  setTimeout(function(){
  card.style.transition='';card.style.transform='';card.style.transformOrigin='';
  inner.style.transition='none';inner.style.opacity=1;
  if(done)done()},420);
  }

